import {initialState,inspect,evaluate,update,csv,parseGuidedCommand} from './engine.mjs';
const $=id=>document.getElementById(id),storage='wexspace.engineering.workshop.v1';let state,plan=false;
try{const x=JSON.parse(localStorage.getItem(storage));if(x?.schema!==initialState().schema)throw Error();evaluate(x.room);state=x;}catch{state=initialState();}
try{if(location.hash.startsWith('#room=')){const r=JSON.parse(decodeURIComponent(location.hash.slice(6)));evaluate(r);if(r.includeCeiling)throw Error();state={...initialState(),room:r};}}catch{$('error').textContent='The shared room link is invalid. The existing workspace is preserved.';}
const fmt=n=>Number(n).toLocaleString('en',{maximumFractionDigits:2});
function say(text,kind='agent'){const el=document.createElement('div');el.className='bubble '+kind;el.textContent=text;$('conversation').append(el);el.scrollIntoView({block:'nearest'});}
function draw(){const {length:l,width:w,height:h}=state.room;let x=Math.min(195,l*28),y=Math.min(145,w*25),z=h*28;const sx=350-(x-y)*.5,sy=250;
 const p=(a,b,c)=>`${sx+(a-b)*.78},${sy+(a+b)*.35-c}`;
 const floor=`${p(0,0,0)} ${p(x,0,0)} ${p(x,y,0)} ${p(0,y,0)}`;
 const svg=plan?`<rect x="${350-x/2}" y="${165-y/2}" width="${x}" height="${y}" fill="#edf4e6" stroke="#416b61" stroke-width="8"/><path d="M${350-x/2+30},${165+y/2} h38" stroke="#f4f7f0" stroke-width="12"/><path d="M${350-x/2+30},${165+y/2} v-38 a38,38 0 0 1 38,38" fill="none" stroke="#7c998a" stroke-width="1.5"/><text x="350" y="${165-y/2-22}" text-anchor="middle">${l} m</text><text x="${350+x/2+18}" y="165">${w} m</text><text x="350" y="170" text-anchor="middle" fill="#537666">${fmt(l*w)} m²</text>`:`<polygon points="${p(0,0,0)} ${p(x,0,0)} ${p(x,0,z)} ${p(0,0,z)}" fill="#d7e4df" stroke="#7a9991"/><polygon points="${p(0,0,0)} ${p(0,y,0)} ${p(0,y,z)} ${p(0,0,z)}" fill="#bdcfc9" stroke="#7a9991"/><polygon points="${floor}" fill="#e5edd5" stroke="#779586" stroke-width="1.6"/><path d="M${p(0,0,z)} L${p(x,0,z)} M${p(0,0,z)} L${p(0,y,z)}" stroke="#41675f" stroke-width="5"/><polygon points="${p(x*.48,0,z*.28)} ${p(x*.75,0,z*.28)} ${p(x*.75,0,z*.73)} ${p(x*.48,0,z*.73)}" fill="#f4f9f6" stroke="#84a79f" stroke-width="2"/><line x1="${sx+x*.78}" y1="${sy+x*.35+20}" x2="${sx+(x-y)*.78}" y2="${sy+(x+y)*.35+20}" stroke="#849d8c"/><text x="${sx+x*.78-y*.39+10}" y="${sy+x*.35+y*.175+39}" text-anchor="middle">${w} m</text><text x="${sx-y*.78/2-25}" y="${sy+y*.35/2+27}" text-anchor="middle">${l} m</text><text x="${sx-24}" y="${sy-z/2}" text-anchor="end">${h} m</text><text x="350" y="330" text-anchor="middle" fill="#587362">Concept diagram · dimensions drive the quantities</text>`;
 $('scene').innerHTML=`<svg viewBox="0 0 700 360" role="img" aria-label="Room ${l} by ${w} metres, height ${h} metres"><title>Room ${l} by ${w} m, ${h} m high</title><g font-family="DM Sans, sans-serif" font-size="14" fill="#49675f">${svg}</g></svg>`;}
function render(){const q=evaluate(state.room);for(const k of ['length','width','height','openings','coverage','coats','waste','paintPack'])$(k).value=state.room[k];$('revision').textContent='REV '+String(state.revision).padStart(2,'0');$('floor').textContent=fmt(q.floor_m2);$('walls').textContent=fmt(q.net_walls_m2);$('paint').textContent=fmt(q.paint_litres);$('packs').textContent=q.paint_packs;$('pack-label').textContent=`× ${state.room.paintPack} L · estimate only`;$('area-label').textContent=`${state.room.length} × ${state.room.width} × ${state.room.height} m · Ceiling excluded`;
 $('schedule').replaceChildren(...[['Wall paint',`${fmt(q.paint_litres)} L`,`${q.paint_packs} × ${q.paint_pack_litres} L`],['Floor tiles',`${q.tile_count} tiles`,`${q.tile_boxes} boxes`],['Ceiling','Excluded','0 m²']].map(row=>{const tr=document.createElement('tr');for(const x of row){const td=document.createElement('td');td.textContent=x;tr.append(td);}return tr;}));
 $('formula').replaceChildren(...q.explanation.map(x=>{const li=document.createElement('li');li.textContent=x;return li;}));
 $('audit').replaceChildren(...[...state.audit].reverse().slice(0,4).map(r=>{const li=document.createElement('li'),b=document.createElement('b'),a=document.createElement('span'),c=document.createElement('code');b.textContent=`REV ${r.from_revision} → ${r.to_revision} · ${r.actor}`;a.textContent=Object.entries(r.patch).map(([k,v])=>`${k}: ${v}`).join(' · ');c.textContent='SHA256 '+r.after_sha256.slice(0,16)+'…';li.append(b,a,document.createElement('br'),c);return li;}));
 if(!state.audit.length){const li=document.createElement('li');li.textContent='No edits yet. Start with a human edit or a guided request.';$('audit').append(li);}draw();}
function uniqueId(){const b=new Uint8Array(16);globalThis.crypto.getRandomValues(b);return 'op-'+[...b].map(x=>x.toString(16).padStart(2,'0')).join('');}
let queue=Promise.resolve();function commit(patch,actor,expected_revision=state.revision,operation_id=uniqueId()){
 const job=queue.then(async()=>{const out=await update(state,{patch,actor,expected_revision,operation_id});state=out.state;localStorage.setItem(storage,JSON.stringify(state));render();$('error').textContent='';return out.result;});queue=job.catch(()=>{});return job;
}
$('room-form').addEventListener('submit',async e=>{e.preventDefault();try{const patch={};for(const k of ['length','width','height','openings','coverage','coats','waste','paintPack']){const n=Number($(k).value);if(n!==state.room[k])patch[k]=n;}if(!Object.keys(patch).length){say('No measurements changed. The current quantities still apply.');return;}const r=await commit(patch,'human');say(`Your edit is revision ${r.revision}. Paint: ${fmt(r.quantities.paint_litres)} L. The agent will inspect this same state.`);}catch(e){$('error').textContent=e.message;}});
$('ask-form').addEventListener('submit',async e=>{e.preventDefault();const text=$('ask').value;say(text,'user');try{const patch=parseGuidedCommand(text),r=await commit(patch,'simulator');say(`Revision ${r.revision}: ${r.room.length} × ${r.room.width} × ${r.room.height} m. Paint is ${fmt(r.quantities.paint_litres)} L, or ${r.quantities.paint_packs} packs of ${r.room.paintPack} L. Ceiling stays excluded. No order placed.`);}catch(e){say(e.message,'rejected');$('error').textContent=e.message;}});
document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{$('ask').value=b.dataset.command;$('ask-form').requestSubmit();}));
$('view-toggle').addEventListener('click',()=>{plan=!plan;$('view-toggle').textContent=plan?'Show room view':'Show plan view';draw();});
function download(name,text,type){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('csv').addEventListener('click',()=>download('wexspace-quantity-schedule.csv',csv(state),'text/csv'));
$('export').addEventListener('click',()=>download('wexspace-engineering-dossier.json',JSON.stringify({...inspect(state),exported_at:new Date().toISOString(),physical_work_authorized:false},null,2),'application/json'));
render();
const objectSchema={type:'object',additionalProperties:false},patchProperties={};for(const k of Object.keys(state.room))patchProperties[k]={type:typeof state.room[k]==='boolean'?'boolean':'number'};
const tools=[{name:'wexspace_engineering_inspect',description:'Read the actual shared room, current revision, explicit requirements, quantities and recent changes. Inspect before editing.',inputSchema:{...objectSchema,properties:{}},annotations:{readOnlyHint:true},execute:async()=>inspect(state)},
{name:'wexspace_engineering_update_room',description:'Change measured room assumptions in the shared visible workspace. Requires exact current revision and a unique operation ID. Ceiling requirement is enforced. Cannot purchase or authorize physical work.',inputSchema:{...objectSchema,properties:{patch:{...objectSchema,properties:patchProperties,minProperties:1},expected_revision:{type:'integer',minimum:0},operation_id:{type:'string',minLength:8,maxLength:96}},required:['patch','expected_revision','operation_id']},annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:true},execute:async x=>{const r=await commit(x.patch,'webmcp',x.expected_revision,x.operation_id);say(`Connected agent changed revision ${r.revision}. The visible quantities and drawing now show its result.`);return r;}},
{name:'wexspace_engineering_export_dossier',description:'Read an exportable preliminary quantity dossier with formulas, assumptions, revision evidence and no purchase authorization.',inputSchema:{...objectSchema,properties:{}},annotations:{readOnlyHint:true},execute:async()=>({...inspect(state),csv:csv(state),physical_work_authorized:false})}];
if(typeof document.modelContext?.registerTool==='function'){let failures=0;for(const t of tools){try{await document.modelContext.registerTool({...t,execute:async x=>{try{return {content:[{type:'text',text:JSON.stringify(await t.execute(x))}]};}catch(e){return {isError:true,content:[{type:'text',text:JSON.stringify({error:e.code||'INPUT_ERROR',message:e.message,revision:state.revision})}]};}}});}catch{failures++;}}$('tool-status').textContent=failures?'Agent registration incomplete':'3 live WebMCP tools';}else $('tool-status').textContent='Browser workspace · agent tools unavailable here';
